-- Deities and Demigods: Pharaonic pantheon divine stat blocks, final batch.
-- Source: Deities and Demigods (2002), Chapter 5, pp. 155-159.
-- Printed 3.0 statistics remain source-of-truth; official 3.5 conversion deltas are recorded separately.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('dd-3.0','deities-and-demigods-3-0','Deities and Demigods','DD','Wizards of the Coast','dnd','3.0',
        'Deities and Demigods (2002): divine ranks, pantheons, salient divine abilities, divine minions, domains, spells, monsters, prestige classes, and ascension.',NULL,1,0,NULL);

UPDATE dnd35_deities SET symbol='Crocodile head with horned and plumed headdress' WHERE source_id='dd-3.0' AND slug='sobek' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Ibis' WHERE source_id='dd-3.0' AND slug='thoth' AND owner_user_id IS NULL;

WITH desired(slug,name,page,description,mechanics) AS (VALUES
('dd-statblock-sobek','Sobek Divine Stat Block','155-156',
 'Sobek is the divine-rank-3 Pharaonic demigod of water, river hazards, crocodiles, and wetlands.',
 '{"deitySlug":"sobek","pantheon":"pharaonic","sourceEdition":"3.0","rankBand":"demigod","divineRank":3,"symbol":"Crocodile head with horned and plumed headdress","homePlane":"Material Plane","alignment":"LE","classes":[{"class":"Rogue","level":20},{"class":"Assassin","level":10}],"creature":{"type":"Outsider","size":"Medium","hitDice":"20d8+160 outsider + 20d6+160 rogue + 10d6+80 assassin","hitPoints":740,"initiative":14,"speed":{"land":60,"swim":60},"armorClass":{"total":46,"dexterity":10,"divine":3,"natural":16,"deflection":7},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"shortspear":"+57/+52/+47/+42 melee, +3 unholy wounding shortspear","shortspearDamage":"1d8+27/19-20/x3","bite":"+49 melee","biteDamage":"2d8+8","spellTouch":{"melee":54,"ranged":48}},"saves":{"fort":38,"ref":40,"will":37},"abilities":{"str":43,"dex":30,"con":27,"int":25,"wis":25,"cha":25},"specialAttacks":{"sneakAttack":"+18d6","deathAttackDc":27,"poisonUse":true,"improvedGrab":{"trigger":"bite hit","effect":"on a hold, deals bite damage every round"}},"specialQualities":{"printedDamageReduction":"38/+4","printedFireResistance":23,"spellResistance":35,"divineAura":{"radiusFeet":30,"dc":20},"rogueFeatures":["evasion","uncanny dodge (cannot be flanked, +4 against traps)","crippling strike","defensive roll","improved evasion","opportunist"],"poisonSaveBonus":5,"teleportWithoutErrorAtWill":true},"salientDivineAbilities":["Alter Size","Alter Form","Call Creatures (crocodiles of all sorts, including fiendish)","Divine Sneak Attack"],"domainPowers":{"animalFriendshipUsesPerDay":3,"evilSpellsCasterLevelBonus":1,"waterTurningUsesPerDay":10},"spellLikeAbilities":{"casterLevel":13,"evilCasterLevel":14,"saveDc":"20 + spell level"},"spellcasting":{"assassinSpellsPerDay":"4/4/4/2","assassinBaseDc":"17 + spell level"},"portfolioSense":"River floods threatening at least one thousand people, instantaneously.","automaticActions":{"skills":["Bluff","Escape Artist","Innuendo","Intimidate"],"freeActionDcMaximum":15,"maximumPerRound":2},"createMagicItems":false,"avatarStatus":"Sobek is rank 3 and does not possess the Avatar salient divine ability; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":["evil","lawful"],"damageReduction":"15/epic","fireResistance":8,"additionalOutsiderSkillPoints":true,"rogue":"Additional +2 against traps under revised rogue rules.","animalDomain":"Use revised animal-domain/wild-empathy semantics where the 3.0 animal friendship granted power no longer applies directly.","defunctSkills":["Innuendo ranks reassigned","Wilderness Lore -> Survival/appropriate revised skills"]}}'),

('dd-statblock-thoth','Thoth Divine Stat Block','157-159',
 'Thoth is the divine-rank-13 intermediate Pharaonic deity of knowledge, wisdom, learning, writing, and scholarship.',
 '{"deitySlug":"thoth","pantheon":"pharaonic","sourceEdition":"3.0","rankBand":"intermediate","divineRank":13,"symbol":"Ibis","homePlane":"The Offering Fields","alignment":"N","classes":[{"class":"Wizard","level":20},{"class":"Cleric","level":10},{"class":"Loremaster","level":10}],"creature":{"type":"Outsider","size":"Medium","hitDice":"20d8+160 outsider + 20d4+160 wizard + 10d8+80 cleric + 10d4+80 loremaster","hitPoints":840,"initiative":"+13, always first","speed":{"land":60},"armorClass":{"total":67,"dexterity":9,"divine":13,"loremasterDodgeSecret":1,"natural":26,"deflection":8},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"scepter":"+62/+57/+52/+47 melee touch","scepterDamage":"as destruction spell","spellTouch":{"melee":61,"ranged":62}},"saves":{"fort":53,"ref":54,"will":56,"intermediateDeityChecksAlways20":true},"abilities":{"str":27,"dex":29,"con":27,"int":46,"wis":32,"cha":27},"specialAttacks":{"turnUndeadPerDay":11},"specialQualities":{"printedDamageReduction":"48/+4","printedFireResistance":33,"spellResistance":65,"divineAura":{"radiusFeet":1300,"dc":31},"familiar":"ibises","loreBonus":28,"greaterLore":true,"trueLore":true,"loremasterSecrets":["Dodge trick","Weapon Trick","one feat","bonus 1st-level spell","bonus 2nd-level spell"],"teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Arcane Mastery","Automatic Metamagic (quicken wizard spells)","Clearsight","Craft Artifact","Divine Skill Focus (Knowledge [arcana])","Divine Skill Focus (Knowledge [history])","Divine Skill Focus (Knowledge [the planes])","Divine Skill Focus (Knowledge [religion])","Divine Spellcasting","Extra Sense Enhancement (penetrating vision)","Increased Spell Resistance","Know Secrets","Power of Truth","Spontaneous Wizard Spells","Supreme Initiative","True Knowledge"],"domainPowers":{"divinationSpellsCasterLevelBonus":1,"magicDomainUseItemsAsWizardLevel":35},"spellLikeAbilities":{"casterLevel":23,"divinationCasterLevel":24,"saveDc":"31 + spell level"},"spellcasting":{"clericSpellsPerDay":"6/9/9/9/8/8/7/7/6/6","clericBaseDc":"23 + spell level","wizardSpellsPerDayLevels0To18":"4/10/10/8/8/8/8/7/7/7/4/3/3/3/3/2/2/2/2","wizardBaseDc":"30 + spell level"},"possessions":{"scepter":"Rod-like scepter delivers a destruction spell heightened to 9th level on a melee touch; Fortitude DC 23 negates; caster level 20; weight 5 lb."},"senses":{"normalRangeMiles":13,"penetratingVisionFeet":130},"portfolioSense":"Discovery, recording, or sharing of any knowledge, instantaneously and thirteen weeks into the past.","automaticActions":{"generalKnowledgeSkills":{"freeActionDcMaximum":25,"untrainedAllowed":true},"specialKnowledgeSkills":{"skills":["Knowledge (arcana)","Knowledge (history)","Knowledge (the planes)","Knowledge (religion)"],"freeActionDcMaximum":38},"maximumPerRound":10},"createMagicItems":{"scope":"any magic item","maximumMarketPriceGp":200000},"avatarStatus":"No Avatar salient divine ability is present in the printed stat block; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":[],"damageReduction":"25/epic","fireResistance":18,"additionalOutsiderSkillPoints":true,"divineSkillFocus":"Apply the official revised Divine Skill Focus treatment.","wizardSpecialization":"Apply revised school-specialization rules where relevant.","defunctSkills":["Alchemy -> Craft (alchemy)","Intuit Direction migrated","Read Lips folded into Spot","Scry ranks reassigned"]}}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,
   category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT
  'dd-rule-'||d.slug,'dd-3.0',d.page,d.slug,d.name,d.description,
  'Use the structured mechanics payload for the printed Deities and Demigods divine stat block. Printed 3.0 values remain source-of-truth; revision3_5 records official conversion deltas.',
  0,NULL,1,'deity','divine-stat-block',0,1,'dd-pharaonic-pantheon',NULL,
  '["deities-and-demigods","pharaonic","deity-stat-block","revision-3.5"]',
  d.mechanics
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_rules r WHERE r.source_id='dd-3.0' AND r.slug=d.slug AND r.owner_user_id IS NULL
);
